  dict(q="Which statement about I² is correct?", opts=["It measures the absolute size of heterogeneity.","It is the proportion of variability beyond chance and depends on study precision.","It decides whether to use random effects.","It is always above 50%."], ans=1, why="Rücker 2008; Higgins & Thompson 2002."),
  dict(q="Which quantity says how large the between-study variance is in effect-size units?", opts=["I²","H²","tau-squared","p-value of Q"], ans=2, why="τ² is on the effect-size scale squared."),
  dict(q="Why does the BCG prediction interval include RR>1 while the pooled CI does not?", opts=["A calculation error.","The prediction interval adds between-study variance and describes a new study's true effect.","Prediction intervals are always symmetric around 1.","The CI is wrong."], ans=1, why="PI = μ̂ ± t√(τ²+SE²) is much wider with large τ²."),
  dict(q="You have 4 studies and I² = 0%. Conclusion?", opts=["The studies are homogeneous.","Heterogeneity cannot be excluded: Q and I² have little power with few studies.","Use fixed effects.","Add more outcomes."], ans=1, why="Low power at small k."),
  dict(q="Is removing the most discordant study to reduce I² acceptable?", opts=["Yes.","No - it is outcome-driven selection; use influence analyses as sensitivity analyses, not for selection.","Only for k>20.","Only if p<0.05."], ans=1, why="It biases the synthesis and is not pre-specified."),
